<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'

type Mode='reviews'|'items'|'claims'|'users'|'stations'|'dictionaries'|'config'|'lab'|'reports'|'content'|'system'
const props=defineProps<{mode:Mode}>();const rows=ref<any[]>([]);const secondary=ref<any[]>([]);const summary=ref<any>(null);const loading=ref(true);const busy=ref(false);const error=ref('');const success=ref('')
const meta:Record<Mode,{id:string;title:string;lead:string}>={
 reviews:{id:'B02',title:'内容审核',lead:'协调员只能处理成员关系覆盖的站点，每次决定都记录审计事件。'},
 items:{id:'B03',title:'物品管理',lead:'审核状态与业务状态分开展示，不把关闭或归还误当作审核结果。'},
 claims:{id:'B04',title:'认领管理',lead:'查看举证状态、唯一保留与交接待办。'},
 users:{id:'B05',title:'用户管理',lead:'仅 ADMIN 可修改角色与账号状态，且不能停用或降级自己。'},
 stations:{id:'B06',title:'站点管理',lead:'读取真实服务站的范围、营业时间、容量与状态。'},
 dictionaries:{id:'B07',title:'字典管理',lead:'查看类别与地点字典的真实条目；版本化写操作仍需审计流程。'},
 config:{id:'B08',title:'匹配参数中心',lead:'查看可追溯的六因子权重、门槛和预处理版本，发布时生成审计记录。'},
 lab:{id:'B09',title:'算法实验室',lead:'展示固定合成基准上 B0–B3 和消融证据，不将合成指标冒充真实校园准确率。'},
 reports:{id:'B10',title:'报表中心',lead:'只展示当前权限范围内的真实数据库计数。'},
 content:{id:'B11',title:'内容运营',lead:'管理帮助文章等内容的发布状态，找回故事另需当事人授权。'},
 system:{id:'B12',title:'系统管理',lead:'查看健康状态与持久任务；失败任务保留错误码，刷新页面不丢失。'},
}
const page=computed(()=>meta[props.mode])
async function load(){loading.value=true;error.value='';rows.value=[];secondary.value=[];summary.value=null;try{if(props.mode==='reviews'){const response=await api<{data:{items:any[]}}>('/items/?review_status=PENDING&page_size=100');rows.value=response.data.items}else if(props.mode==='items'){const response=await api<{data:{items:any[]}}>('/items/?page_size=100');rows.value=response.data.items}else if(props.mode==='claims'){const response=await api<{data:{items:any[]}}>('/claims/?page_size=100');rows.value=response.data.items}else if(props.mode==='users'){const response=await api<{data:{items:any[]}}>('/admin/users/?page_size=100');rows.value=response.data.items}else if(props.mode==='stations'){const response=await api<{data:{items:any[]}}>('/admin/stations/?page_size=100');rows.value=response.data.items}else if(props.mode==='dictionaries'){const response=await api<{data:{categories:any[];locations:any[]}}>('/items/metadata/');rows.value=response.data.categories;secondary.value=response.data.locations}else if(props.mode==='config'){const response=await api<{data:{items:any[]}}>('/admin/matching-configs/?page_size=100');rows.value=response.data.items}else if(props.mode==='lab'){const response=await api<{data:any}>('/admin/benchmark/');summary.value=response.data}else if(props.mode==='reports'){const response=await api<{data:any}>('/admin/overview/');summary.value=response.data}else if(props.mode==='content'){const response=await api<{data:{items:any[]}}>('/admin/help/?page_size=100');rows.value=response.data.items}else{const [health,tasks]=await Promise.all([api<{data:any}>('/health/'),api<{data:{items:any[]}}>('/admin/tasks/?page_size=100')]);summary.value=health.data;rows.value=tasks.data.items}}catch(reason){error.value=reason instanceof ApiError?reason.message:'管理数据加载失败'}finally{loading.value=false}}
async function review(id:string,decision:'APPROVE'|'REJECT'){busy.value=true;try{await api(`/items/${id}/review/`,{method:'POST',body:JSON.stringify({decision,note:'通过运营工作台处理'})});success.value='审核决定已记录';await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'审核失败'}finally{busy.value=false}}
async function toggleUser(entry:any){busy.value=true;try{const target=entry.account_status==='ACTIVE'?'SUSPENDED':'ACTIVE';await api(`/admin/users/${entry.id}/`,{method:'PATCH',body:JSON.stringify({account_status:target})});await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'用户更新失败'}finally{busy.value=false}}
async function publishConfig(id:number){busy.value=true;try{await api(`/admin/matching-configs/${id}/publish/`,{method:'POST'});success.value='算法配置已发布并记录审计';await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'发布失败'}finally{busy.value=false}}
async function toggleContent(entry:any){busy.value=true;try{await api(`/admin/help/${entry.id}/`,{method:'PATCH',body:JSON.stringify({is_published:!entry.is_published,published_at:!entry.is_published?new Date().toISOString():entry.published_at})});await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'内容更新失败'}finally{busy.value=false}}
onMounted(load);watch(()=>props.mode,load)
</script>
<template><div class="page admin-resource"><header><div><p class="eyebrow">{{page.id}} · AUDITED OPERATIONS</p><h1 class="page-title">{{page.title}}</h1><p class="page-lead">{{page.lead}}</p></div><RouterLink class="button button-ghost" to="/admin/overview">返回总览</RouterLink></header><p v-if="success" class="notice success">{{success}}</p><p v-if="loading" class="state">正在读取权限范围内的真实数据…</p><p v-else-if="error" class="state error">{{error}}</p><template v-else><section v-if="mode==='lab'&&summary" class="lab"><div class="panel lab-summary"><p class="eyebrow">SYNTHETIC EVIDENCE ONLY</p><h2>{{summary.model_version}}</h2><dl><div><dt>测试查询</dt><dd>{{summary.test_query_count}}</dd></div><div><dt>候选</dt><dd>{{summary.candidate_count}}</dd></div><div><dt>资格召回</dt><dd>{{(summary.candidate_eligibility_recall*100).toFixed(0)}}%</dd></div></dl><p>{{summary.limitations.join(' ')}}</p></div><div class="method-grid"><article v-for="(value,key) in summary.methods" :key="key" class="panel"><span>{{key}}</span><strong>MRR {{value.metrics.mrr.toFixed(3)}}</strong><small>Hit@1 {{value.metrics['hit@1'].toFixed(3)}} · n={{value.query_count}}</small></article></div></section><section v-else-if="mode==='reports'&&summary" class="report-grid"><article v-for="(value,key) in summary" :key="key" class="panel report-card"><span>{{key}}</span><strong v-if="typeof value!=='object'">{{value}}</strong><pre v-else>{{JSON.stringify(value,null,2)}}</pre></article></section><section v-else-if="mode==='dictionaries'" class="dict-grid"><div class="panel"><h2>类别字典 · {{rows.length}}</h2><div class="chips"><span v-for="entry in rows" :key="entry.id">{{entry.name}} <small>{{entry.code}}</small></span></div></div><div class="panel"><h2>地点字典 · {{secondary.length}}</h2><div class="chips"><span v-for="entry in secondary" :key="entry.id">{{entry.name}} <small>{{entry.code}}</small></span></div></div></section><section v-else class="data-table"><article v-for="entry in rows" :key="entry.id" class="panel data-row"><template v-if="mode==='reviews'||mode==='items'"><div><span>{{entry.kind}} · {{entry.review_status}}</span><h2>{{entry.title}}</h2><p>{{entry.category_name}} · {{entry.location_name}} · {{entry.business_status}}</p></div><div v-if="mode==='reviews'" class="actions"><button class="button button-ghost" :disabled="busy" @click="review(entry.id,'REJECT')">驳回</button><button class="button button-brand" :disabled="busy" @click="review(entry.id,'APPROVE')">通过</button></div><RouterLink v-else :to="`/items/${entry.id}`">查看 <AppIcon name="arrow"/></RouterLink></template><template v-else-if="mode==='claims'"><div><span>{{entry.status}}</span><h2>{{entry.item_title}}</h2><p>{{entry.statement}}</p></div><RouterLink :to="`/claims/${entry.id}`">处理 <AppIcon name="arrow"/></RouterLink></template><template v-else-if="mode==='users'"><div><span>{{entry.role}} · {{entry.account_status}}</span><h2>{{entry.display_name}}</h2><p>@{{entry.username}} · {{entry.email||'无邮箱'}}</p></div><button class="button button-ghost" :disabled="busy" @click="toggleUser(entry)">{{entry.account_status==='ACTIVE'?'停用':'恢复'}}</button></template><template v-else-if="mode==='stations'"><div><span>{{entry.status}}</span><h2>{{entry.name}}</h2><p>{{entry.location.name}} · {{entry.address}} · 容量 {{entry.capacity}}</p></div><RouterLink :to="`/stations/${entry.id}`">查看 <AppIcon name="arrow"/></RouterLink></template><template v-else-if="mode==='config'"><div><span>{{entry.is_published?'已发布':'草案'}} · {{entry.version}}</span><h2>{{entry.name}}</h2><p>{{entry.weights}}</p></div><button v-if="!entry.is_published" class="button button-brand" :disabled="busy" @click="publishConfig(entry.id)">发布</button></template><template v-else-if="mode==='content'"><div><span>{{entry.is_published?'已发布':'未发布'}} · {{entry.category}}</span><h2>{{entry.title}}</h2><p>{{entry.body}}</p></div><button class="button button-ghost" :disabled="busy" @click="toggleContent(entry)">{{entry.is_published?'下架':'发布'}}</button></template><template v-else><div><span>{{entry.status}} · {{entry.task_type}}</span><h2>任务 #{{entry.id}}</h2><p>{{entry.error_code||'无错误码'}} · {{entry.error_message||'正常'}}</p></div><strong>{{entry.progress}}%</strong></template></article><div v-if="!rows.length" class="empty">当前权限范围内没有对应数据。</div></section></template></div></template>
<style scoped>.admin-resource>header{display:flex;justify-content:space-between;align-items:end;gap:25px}.notice,.state{padding:14px;border-radius:10px}.success{color:var(--ct-success);background:rgba(82,211,154,.07)}.state{display:grid;place-items:center;min-height:320px}.error{color:var(--ct-danger)}.data-table{display:grid;gap:10px;margin-top:34px}.data-row{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:20px;box-shadow:none}.data-row span,.data-row p{color:var(--ct-text-muted)}.data-row h2,.data-row p{margin:5px 0}.data-row a{display:flex;align-items:center;gap:6px;color:var(--ct-brand)}.actions{display:flex;gap:8px}.dict-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:34px}.dict-grid>.panel{padding:24px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chips>span{padding:9px;border:1px solid var(--ct-border);border-radius:9px}.chips small{color:var(--ct-text-muted)}.lab{margin-top:34px}.lab-summary{padding:26px}.lab-summary dl{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--ct-border)}.lab-summary dl div{padding:16px;background:var(--ct-bg-soft)}.lab-summary dt{color:var(--ct-text-muted)}.lab-summary dd{margin:5px 0;color:var(--ct-brand);font-size:26px}.lab-summary>p{color:var(--ct-text-muted);line-height:1.7}.method-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:12px}.method-grid article{padding:18px}.method-grid span,.method-grid strong,.method-grid small{display:block}.method-grid span,.method-grid small{color:var(--ct-text-muted);font-size:10px}.method-grid strong{margin:9px 0;color:var(--ct-brand)}.report-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:34px}.report-card{padding:20px}.report-card span{color:var(--ct-text-muted)}.report-card strong{display:block;margin-top:8px;color:var(--ct-brand);font-size:28px}.report-card pre{overflow:auto;font-size:10px}.empty{padding:60px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:15px;text-align:center}@media(max-width:850px){.method-grid,.report-grid{grid-template-columns:1fr 1fr}.dict-grid{grid-template-columns:1fr}}@media(max-width:600px){.admin-resource>header{align-items:start;flex-direction:column}.data-row{align-items:start;flex-direction:column}.method-grid,.report-grid{grid-template-columns:1fr}}</style>
